-- Awakened forms and the reworked Signatures: new Balance Config fields shared.awaken.{form,mark},
-- shared.skills.lance.aim, shared.skills.shield.{size,bashCd,bashMul,bashDur,awk.*}, shared.skills.sigil.awk.*,
-- shared.skills.hawk.awk.*, shared.skills.flask.awk.*. Patched into the live config_schema so publish_config accepts them;
-- their defaults keep the current behaviour (Lance faces the walk, no Shield Bash, Awakening only hits harder) until an
-- admin publishes the pass that turns them on.
update public.config_schema set schema = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(schema,
  '{properties,shared,properties,awaken}',
  $j${"description":"Awakening","default":{},"type":"object","properties":{"links":{"default":2,"description":"Max-level Links needed (consumed unless keep is 1)","type":"number","minimum":1,"maximum":3},"stages":{"default":1,"description":"Full Stages the Links must have been max level and equipped","type":"number","minimum":1,"maximum":5},"sigDmg":{"default":1.3,"description":"Awakened Signature Skill damage ×","type":"number","minimum":0,"maximum":10},"grant":{"default":0,"description":"Skill Line skills given right away when Awakening (in listed order, into free attack slots)","type":"number","minimum":0,"maximum":3},"grantLv":{"default":1,"description":"Level of the Skill Line skills given at Awakening","type":"number","minimum":1,"maximum":8},"wLine":{"default":1,"description":"Level-up offer weight × for Skill Line skills after Awakening","type":"number","minimum":0,"maximum":10},"keep":{"default":0,"description":"Awakening keeps the Links equipped (1) or consumes them (0)","type":"number","minimum":0,"maximum":1},"slots":{"default":0,"description":"Extra attack slots after Awakening","type":"number","minimum":0,"maximum":2},"form":{"default":0,"description":"Awakened Signature takes a new form and the Skill Line skills combo with it (1), or it only hits harder (0)","type":"number","minimum":0,"maximum":1},"mark":{"default":1.5,"description":"Skill Line skills aim at the Awakened Signature's latest strike when it is this recent (s)","type":"number","minimum":0,"maximum":600}}}$j$::jsonb),
  '{properties,shared,properties,skills,properties,lance}',
