00000},"max":{"description":"Upper limit","type":"number","minimum":-1000000,"maximum":1000000}}},"tick":{"default":0.35,"description":"Damage interval (s)","type":"number","minimum":0,"maximum":600},"evo":{"description":"Changes applied when the skill evolves","default":{},"type":"object","properties":{"rMul":{"default":1.35,"description":"Radius multiplier","type":"number","minimum":0,"maximum":10},"n":{"default":2,"description":"Sigils per cast","type":"number","minimum":1,"maximum":5}}},"awk":{"description":"Archmage (Awakened, awaken.form 1): Wandering Sigils; Starfall aims at them, Time Warp freezes","default":{},"type":"object","properties":{"nAdd":{"default":0,"description":"Extra sigils per cast","type":"number","minimum":0,"maximum":4},"rMul":{"default":1,"description":"Radius ×","type":"number","minimum":0,"maximum":10},"durMul":{"default":1,"description":"Lasts ×","type":"number","minimum":0,"maximum":10},"spd":{"default":30,"description":"Drift speed toward the thickest crowd","type":"number","minimum":0,"maximum":300},"pull":{"default":22,"description":"Pull speed toward the sigil centre (Gathered)","type":"number","minimum":0,"maximum":220},"trail":{"default":0.3,"description":"Leaves a trail mark every (s)","type":"number","minimum":0,"maximum":600},"trailDur":{"default":1.4,"description":"Trail mark lasts (s)","type":"number","minimum":0,"maximum":600},"trailR":{"default":0.35,"description":"Trail mark radius × sigil radius","type":"number","minimum":0,"maximum":1},"trailMul":{"default":0.5,"description":"Trail mark damage × sigil damage","type":"number","minimum":0,"maximum":1},"echo":{"default":0.5,"description":"Mana Nova also bursts from each sigil at this damage ×","type":"number","minimum":0,"maximum":1},"warpChill":{"default":1,"description":"Time Warp: chance each tick adds a frost stack to a monster inside (3 stacks = Frozen)","type":"number","minimum":0,"maximum":1}}}}}$j$::jsonb),
